type LRUCache struct{c int;q []int;v map[int]int};func Constructor(c int)LRUCache{return LRUCache{c,nil,map[int]int{}}};func(x *LRUCache)get(k int)int{v,ok:=x.v[k];if !ok{return-1};x.put(k,v);return v};func(x *LRUCache)put(k,v int){for i,n:=range x.q{if n==k{x.q=append(x.q[:i],x.q[i+1:]...);break}};if x.c==0{return};if len(x.q)==x.c{delete(x.v,x.q[0]);x.q=x.q[1:]};x.q=append(x.q,k);x.v[k]=v}
